const sharp = require\('sharp'\);
const path = require\('path'\);
const fs = require\('fs'\);

const src = 'C:/Users/vevle/Downloads/Logo sistema joyero.jpg';
const outDir = path.join\(__dirname, 'public', 'icons'\);

async function generate\(\) {
  // 512x512 PNG for electron-builder
  await sharp\(src\).resize\(512, 512, { fit: 'contain', background: { r: 255, g: 255, b: 255, alpha: 1 } }\).png\(\).toFile\(path.join\(outDir, 'icon.png'\)\);

  // 256x256 PNG for window icon
  await sharp\(src\).resize\(256, 256, { fit: 'contain', background: { r: 255, g: 255, b: 255, alpha: 1 } }\).png\(\).toFile\(path.join\(outDir, 'icon-256.png'\)\);

  // Generate ICO with multiple sizes \(16, 32, 48, 64, 128, 256\)
  const sizes = [16, 32, 48, 64, 128, 256];
  const buffers = [];
  for \(const size of sizes\) {
    const buf = await sharp\(src\).resize\(size, size, { fit: 'contain', background: { r: 255, g: 255, b: 255, alpha: 1 } }\).png\(\).toBuffer\(\);
    buffers.push\({ size, buf }\);
  }

  // Build ICO file manually
  const numImages = buffers.length;
  // ICO header: 6 bytes
  // ICO dir entries: 16 bytes each
  const headerSize = 6 + numImages * 16;
  let offset = headerSize;
  const dirEntries = [];
  for \(const { size, buf } of buffers\) {
    dirEntries.push\({ w: size >= 256 ? 0 : size, h: size >= 256 ? 0 : size, dataSize: buf.length, offset }\);
    offset += buf.length;
  }

  const ico = Buffer.alloc\(offset\);
  // Header
  ico.writeUInt16LE\(0, 0\); // reserved
  ico.writeUInt16LE\(1, 2\); // type: icon
  ico.writeUInt16LE\(numImages, 4\); // count

  let pos = 6;
  for \(const entry of dirEntries\) {
    ico.writeUInt8\(entry.w, pos\);
    ico.writeUInt8\(entry.h, pos + 1\);
    ico.writeUInt8\(0, pos + 2\); // palette
    ico.writeUInt8\(0, pos + 3\); // reserved
    ico.writeUInt16LE\(1, pos + 4\); // color planes
    ico.writeUInt16LE\(32, pos + 6\); // bits per pixel
    ico.writeUInt32LE\(entry.dataSize, pos + 8\);
    ico.writeUInt32LE\(entry.offset, pos + 12\);
    pos += 16;
  }

  for \(const { buf } of buffers\) {
    buf.copy\(ico, pos\);
    pos += buf.length;
  }

  fs.writeFileSync\(path.join\(outDir, 'icon.ico'\), ico\);
  console.log\('Done: icon.png, icon-256.png, icon.ico'\);
}

