const sharp = require\('sharp'\);
const path = require\('path'\);
const fs = require\('fs'\);

const src = 'C:/Users/vevle/Downloads/Logo sistema joyero.jpg';
const outDir = path.join\(__dirname, 'public', 'icons'\);

async function generate\(\) {
  // Remove white background by making white pixels transparent
  const raw = sharp\(src\).flatten\({ background: { r: 255, g: 255, b: 255 } }\);
  const { data, info } = await sharp\(src\).ensureAlpha\(\).raw\(\).toBuffer\({ resolveWithObject: true }\);

  // Make near-white pixels transparent
  for \(let i = 0; i < data.length; i += 4\) {
    const r = data[i], g = data[i+1], b = data[i+2];
    if \(r > 240 && g > 240 && b > 240\) {
      data[i+3] = 0; // transparent
    }
  }

  const base = sharp\(data, { raw: { width: info.width, height: info.height, channels: 4 } }\).png\(\);

  // 512x512 PNG
  await base.clone\(\).resize\(512, 512, { fit: 'contain', background: { r: 0, g: 0, b: 0, alpha: 0 } }\).toFile\(path.join\(outDir, 'icon.png'\)\);

  // 256x256 PNG
  await base.clone\(\).resize\(256, 256, { fit: 'contain', background: { r: 0, g: 0, b: 0, alpha: 0 } }\).toFile\(path.join\(outDir, 'icon-256.png'\)\);

  // ICO with multiple sizes
  const sizes = [16, 32, 48, 64, 128, 256];
  const buffers = [];
  for \(const size of sizes\) {
    const buf = await base.clone\(\).resize\(size, size, { fit: 'contain', background: { r: 0, g: 0, b: 0, alpha: 0 } }\).png\(\).toBuffer\(\);
    buffers.push\({ size, buf }\);
  }

  // Build ICO
  const numImages = buffers.length;
  const headerSize = 6 + numImages * 16;
  let offset = headerSize;
  const dirEntries = [];
  for \(const { size, buf } of buffers\) {
    dirEntries.push\({ w: size >= 256 ? 0 : size, h: size >= 256 ? 0 : size, dataSize: buf.length, offset }\);
    offset += buf.length;
  }

  const ico = Buffer.alloc\(offset\);
  ico.writeUInt16LE\(0, 0\);
  ico.writeUInt16LE\(1, 2\);
  ico.writeUInt16LE\(numImages, 4\);

  let pos = 6;
  for \(const entry of dirEntries\) {
    ico.writeUInt8\(entry.w, pos\);
    ico.writeUInt8\(entry.h, pos + 1\);
    ico.writeUInt8\(0, pos + 2\);
    ico.writeUInt8\(0, pos + 3\);
    ico.writeUInt16LE\(1, pos + 4\);
    ico.writeUInt16LE\(32, pos + 6\);
    ico.writeUInt32LE\(entry.dataSize, pos + 8\);
    ico.writeUInt32LE\(entry.offset, pos + 12\);
    pos += 16;
  }

  for \(const { buf } of buffers\) {
    buf.copy\(ico, pos\);
    pos += buf.length;
  }

  fs.writeFileSync\(path.join\(outDir, 'icon.ico'\), ico\);
  console.log\('Done: transparent icons generated'\);
}

